import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="IC AGUDA Y EAP"; N=7   # franja roja: vital (por defecto)
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:20px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("EDEMA AGUDO DE PULMÓN",128)+big(f'¿FUNCIONA LA FUROSEMIDA? <span style="color:{R}">MÍRALO A LAS 2 HORAS</span>',98)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Insuficiencia cardiaca aguda: perfil, dosis, respuesta diurética y qué hacer según la presión. Con ficha final.</div>',cover=True),
page(2,N,T,kicker("RECONOCE")+big("CUATRO FORMAS",150,nowrap=True)+rows(line("IC izquierda descompensada"),line("IC derecha descompensada"),line("Edema agudo de pulmón",True),f'<div style="border-top:4px solid {K};padding-top:22px;font-size:42px;font-weight:800;line-height:1.3;color:{R}">Shock cardiogénico: hipoperfusión, lactato &gt; 2 mmol/l</div>')+note("Hipoperfusión no es lo mismo que hipotensión: mira la piel, la consciencia, la diuresis y el lactato.")),
page(3,N,T,kicker("BUSCA LA CAUSA")+big("CHAMPIT",210,R,True)+rows(row("C","Coronario: síndrome coronario agudo"),row("H","Hipertensión: emergencia hipertensiva"),row("A","Arritmia"),row("M","Mecánica: valvulopatía aguda, rotura"),row("P","TEP (Pulmonary embolism)"),row("I · T","Infección · Taponamiento"))+note("NT-proBNP &lt; 300 pg/ml (o BNP &lt; 100) hace improbable el origen cardiaco. ECG, troponina y ecografía, siempre.")),
page(4,N,T,kicker("DESCONGESTIONA")+big("FUROSEMIDA IV",150,R,True)+rows(row("Sin diurético previo","20–40 mg"),row("Si ya lo tomaba","1–2 veces su dosis oral diaria"))+big("A LAS 2 H, ¿RESPONDE?",100,nowrap=True)+rows(row("Sodio en orina","≥ 50–70 mEq/l"),row("o diuresis","≥ 100–150 ml/h en 6 h"))+note("Si no responde: dobla la dosis IV o añade acetazolamida 500 mg IV o una tiazida. Las guías dan cifras algo distintas: individualiza.")),
page(5,N,T,kicker("RESPIRA")+big("VMNI PRONTO",180,R,True)+'<div style="font-size:48px;font-weight:800;line-height:1.2">Si FR &gt; 25 y SatO2 &lt; 90 %</div>'+rows(row("CPAP","7–15 cmH2O"),row("BiPAP","Si hay hipercapnia o falla la CPAP"),row("Oxígeno","Solo si SatO2 &lt; 90 %"))+note("Si fracasa la ventilación no invasiva, intubación sin demora. Precaución con la hipotensión.")),
page(6,N,T,kicker("LA PRESIÓN DECIDE")+big("PAS &gt; 110",180,R,True)+rows(row("Nitroglicerina IV","Perfusión, titulando (5–200 µg/min)"),row("PAS &lt; 90 + hipoperfusión","Inotrópico: dobutamina"),row("Shock","Noradrenalina y UCI"),line("Morfina: no de rutina. Solo en dolor o ansiedad intensos y seleccionando mucho",True))+note("Nitroglicerina: contraindicada con PAS &lt; 90; precaución entre 90 y 110.")),
page(7,N,T,ficha_body("IC AGUDA · EAP","Adulto",[("FORMA","Izquierda, derecha, EAP o shock (lactato &gt; 2 mmol/l)"),("CAUSA","CHAMPIT: coronario, HTA, arritmia, mecánica, TEP, infección, taponamiento"),("PRUEBAS","NT-proBNP &lt; 300 (BNP &lt; 100): improbable. ECG, troponina, eco"),("FUROSEMIDA","IV 20–40 mg; si la tomaba, 1–2 veces su dosis oral diaria",True),("¿RESPONDE?","A las 2 h: Na orina ≥ 50–70 mEq/l o diuresis ≥ 100–150 ml/h. Si no: doblar o acetazolamida/tiazida"),("RESPIRA","O2 si SatO2 &lt; 90 %. VMNI si FR &gt; 25 y SatO2 &lt; 90 %",True),("PAS","&gt; 110: nitroglicerina. &lt; 90 con hipoperfusión: dobutamina. Shock: noradrenalina"),("MORFINA","No de rutina")],"Guías ESC de insuficiencia cardiaca 2026 y 2021; consenso ICA-SEMES 2011",size=116,fs=27),ficha="12"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","ica-eap")
